"""
Tests of the impulse response analysis in statsmodels.tsa.vector_ar.irf

Reference values come from

* closed forms: the MA matrices of a VAR(p) are the top-left block of the
  powers of the companion matrix, the orthogonalized ones post-multiply
  them by the Cholesky factor of sigma_u, the cumulative effects are their
  partial sums and the long-run effects are (I - A_1 - ... - A_p)^-1;
* the R package vars (results/results_var_data.py, generated by var.R);
* the delta-method covariances of Lütkepohl (2005, Section 3.7), computed
  here with a numerical Jacobian of the closed forms instead of the
  analytical derivatives used by the code.
"""

import numpy as np
from numpy.testing import assert_allclose
import pytest
from scipy import linalg, stats

from statsmodels.datasets import macrodata
from statsmodels.tsa.vector_ar.hypothesis_test_results import ErrorBand
from statsmodels.tsa.vector_ar.svar_model import SVAR
from statsmodels.tsa.vector_ar.var_model import VAR

PERIODS = 4
NAMES = ["realgdp", "realcons", "realinv"]


@pytest.fixture(scope="module")
def macro_data():
    data = macrodata.load_pandas().data[NAMES]
    return np.log(data).diff().dropna().reset_index(drop=True)


@pytest.fixture(scope="module")
def macro_res(macro_data):
    return VAR(macro_data).fit(maxlags=2)


@pytest.fixture(scope="module")
def macro_svar_res(macro_data):
    a = np.asarray([[1, 0, 0], ["E", 1, 0], ["E", "E", 1]], dtype="U")
    b = np.asarray([["E", 0, 0], [0, "E", 0], [0, 0, "E"]], dtype="U")
    return SVAR(macro_data.values, svar_type="AB", A=a, B=b).fit(maxlags=2)


@pytest.fixture(scope="module")
def var1_res():
    rng = np.random.default_rng(20261121)
    nobs = 400
    a = np.array([[0.5, 0.2], [-0.3, 0.4]])
    chol = np.linalg.cholesky(np.array([[1.0, 0.3], [0.3, 0.5]]))
    e = rng.standard_normal((nobs, 2)) @ chol.T
    y = np.zeros((nobs, 2))
    for t in range(1, nobs):
        y[t] = a @ y[t - 1] + e[t]
    return VAR(y).fit(maxlags=1)


def _companion_ma(coefs, periods):
    # Phi_h is the top-left block of the h-th power of the companion matrix
    p, k, _ = coefs.shape
    comp = np.zeros((k * p, k * p))
    comp[:k] = np.hstack(coefs)
    comp[k:, :-k] = np.eye(k * (p - 1))
    return np.array(
        [np.linalg.matrix_power(comp, h)[:k, :k] for h in range(periods + 1)]
    )


def _vech_pairs(k):
    # (row, column) of the elements of vech(sigma_u), stacked by columns
    return [(r, c) for c in range(k) for r in range(c, k)]


def _effects(alpha, vech_sigma, k, p, kind, orth, periods, sign):
    coefs = alpha.reshape((k, k * p), order="F")
    coefs = np.array([coefs[:, i * k : (i + 1) * k] for i in range(p)])
    if kind == "lr":
        out = np.linalg.inv(np.eye(k) - coefs.sum(0))[None]
    else:
        out = _companion_ma(coefs, periods)
        if kind == "cum":
            out = out.cumsum(0)
    if orth:
        sigma = np.zeros((k, k))
        for value, (r, c) in zip(vech_sigma, _vech_pairs(k), strict=True):
            sigma[r, c] = sigma[c, r] = value
        out = out @ (np.linalg.cholesky(sigma) * sign)
    return np.array([m.ravel(order="F") for m in out])


def _jacobian(func, x0):
    step = 1e-6 * np.max(np.abs(x0))
    cols = []
    for i in range(x0.shape[0]):
        up = x0.copy()
        down = x0.copy()
        up[i] += step
        down[i] -= step
        cols.append((func(up) - func(down)) / (2 * step))
    return np.stack(cols, axis=-1)


def _delta_method_cov(res, kind, orth, periods, sign):
    k, p, nobs = res.neqs, res.k_ar, res.nobs
    sigma = np.asarray(res.sigma_u)
    alpha = np.hstack(res.coefs).ravel(order="F")
    pairs = _vech_pairs(k)
    vech_sigma = np.array([sigma[r, c] for r, c in pairs])
    # covariance of vec([A_1, ..., A_p]): drop the deterministic terms
    n_det = k * res.k_exog
    cov_alpha = np.asarray(res.cov_params())[n_det:, n_det:]
    # asymptotic covariance of sqrt(T) vech(sigma_u) under normality:
    # cov(s_ij, s_kl) = s_ik s_jl + s_il s_jk
    cov_sigma = np.array(
        [
            [sigma[i, m] * sigma[j, n] + sigma[i, n] * sigma[j, m] for m, n in pairs]
            for i, j in pairs
        ]
    )

    def f_alpha(a):
        return _effects(a, vech_sigma, k, p, kind, orth, periods, sign)

    def f_sigma(s):
        return _effects(alpha, s, k, p, kind, orth, periods, sign)

    jac_alpha = _jacobian(f_alpha, alpha)
    covs = np.array([ja @ cov_alpha @ ja.T for ja in jac_alpha])
    if orth:
        jac_sigma = _jacobian(f_sigma, vech_sigma)
        covs += np.array([js @ cov_sigma @ js.T for js in jac_sigma]) / nobs
    return covs


def test_irf_var1_closed_form(var1_res):
    irf = var1_res.irf(8)
    a = var1_res.coefs[0]
    chol = np.linalg.cholesky(var1_res.sigma_u)
    expected = np.array([np.linalg.matrix_power(a, h) for h in range(9)])
    assert_allclose(irf.irfs, expected, rtol=1e-10)
    assert_allclose(irf.orth_irfs, expected @ chol, rtol=1e-10)
    assert_allclose(irf.cum_effects, expected.cumsum(0), rtol=1e-10)
    assert_allclose(irf.orth_cum_effects, expected.cumsum(0) @ chol, rtol=1e-10)
    lr = np.linalg.inv(np.eye(2) - a)
    assert_allclose(irf.lr_effects, lr, rtol=1e-10)
    assert_allclose(irf.orth_lr_effects, lr @ chol, rtol=1e-10)
    assert_allclose(irf.P, chol, rtol=1e-12)


def test_irf_var2_companion_and_long_run(macro_res):
    irf = macro_res.irf(10)
    assert_allclose(irf.irfs, _companion_ma(macro_res.coefs, 10), rtol=1e-10)
    lr = np.linalg.inv(np.eye(3) - macro_res.coefs.sum(0))
    assert_allclose(irf.lr_effects, lr, rtol=1e-10)
    # The long-run effects are the limit of the cumulative effects
    long_irf = macro_res.irf(400)
    assert_allclose(long_irf.cum_effects[-1], irf.lr_effects, rtol=1e-8)
    assert_allclose(long_irf.orth_cum_effects[-1], irf.orth_lr_effects, rtol=1e-8)


def test_cum_effects_r_vars(macro_res):
    # Cumulated non-orthogonalized and orthogonalized responses from the R
    # package vars, irf(est, n.ahead=5, boot=F, orth=...), see var.R
    from .results.results_var_data import var_results

    irf = macro_res.irf(5)
    r_irf = var_results.irf.item()
    r_orth = var_results.orthirf.item()
    for j, name in enumerate(NAMES):
        expected = r_irf[name].view((float, 3), type=np.ndarray).cumsum(0)
        assert_allclose(irf.cum_effects[:, :, j], expected, rtol=1e-6)
        expected = r_orth[name].view((float, 3), type=np.ndarray).cumsum(0)
        assert_allclose(irf.orth_cum_effects[:, :, j], expected, rtol=1e-6)


def test_irf_user_decomposition(macro_res):
    # A lower triangular factor of sigma_u with a negative diagonal element
    sign = np.array([1.0, -1.0, 1.0])
    p = np.linalg.cholesky(macro_res.sigma_u) * sign
    irf = macro_res.irf(PERIODS, var_decomp=p)
    phis = _companion_ma(macro_res.coefs, PERIODS)
    assert_allclose(irf.P, p, rtol=1e-12)
    assert_allclose(irf.orth_irfs, phis @ p, rtol=1e-10)
    assert_allclose(irf.orth_cum_effects, phis.cumsum(0) @ p, rtol=1e-10)
    assert_allclose(irf.orth_lr_effects, irf.lr_effects @ p, rtol=1e-10)


@pytest.mark.parametrize("orth", [False, True])
@pytest.mark.parametrize("kind", ["irf", "cum"])
@pytest.mark.parametrize("flip", [False, True])
def test_asymptotic_cov_delta_method(macro_res, kind, orth, flip):
    sign = np.array([1.0, -1.0, 1.0]) if flip else np.ones(3)
    var_decomp = np.linalg.cholesky(macro_res.sigma_u) * sign if flip else None
    irf = macro_res.irf(PERIODS, var_decomp=var_decomp)
    expected = _delta_method_cov(macro_res, kind, orth, PERIODS, sign)
    if kind == "irf":
        cov = irf.cov(orth=orth)
        stderr = irf.stderr(orth=orth)
    else:
        cov = irf.cum_effect_cov(orth=orth)
        stderr = irf.cum_effect_stderr(orth=orth)
    # atol: the numerical Jacobian is accurate relative to the scale of the
    # whole matrix, and some entries are zero (e.g. at horizon 0)
    atol = 1e-7 * np.max(np.abs(expected))
    assert_allclose(cov, expected, rtol=1e-6, atol=atol)
    # stderr[h, i, j] is the standard error of the (i, j) response
    se = np.sqrt(np.diagonal(expected, axis1=1, axis2=2))
    se = se.reshape((PERIODS + 1, 3, 3), order="F")
    assert_allclose(stderr, se, rtol=1e-6, atol=np.sqrt(atol))


def test_lr_effect_cov_delta_method(macro_res):
    irf = macro_res.irf(PERIODS)
    expected = _delta_method_cov(macro_res, "lr", False, PERIODS, np.ones(3))[0]
    assert_allclose(irf.lr_effect_cov(orth=False), expected, rtol=1e-6)
    se = np.sqrt(np.diag(expected)).reshape((3, 3), order="F")
    assert_allclose(irf.lr_effect_stderr(orth=False), se, rtol=1e-6)


def test_svar_irf_closed_form(macro_svar_res):
    res = macro_svar_res
    irf = res.irf(PERIODS)
    p = np.linalg.solve(res.A, res.B)
    phis = _companion_ma(res.coefs, PERIODS)
    # atol: the upper triangle of A^-1 B is zero, up to rounding in the
    # inverse of A
    atol = 1e-12 * np.abs(p).max()
    assert_allclose(irf.P, p, rtol=1e-12, atol=atol)
    assert_allclose(irf.svar_irfs, phis @ p, rtol=1e-10, atol=atol)
    assert_allclose(irf.svar_cum_effects, phis.cumsum(0) @ p, rtol=1e-10, atol=atol)
    lr = np.linalg.inv(np.eye(3) - res.coefs.sum(0))
    assert_allclose(irf.svar_lr_effects, lr @ p, rtol=1e-10)


@pytest.mark.parametrize("cum", [False, True])
@pytest.mark.parametrize("orth", [False, True])
def test_errband_mc_quantiles(macro_res, orth, cum):
    # The Monte Carlo band is the pair of empirical quantiles of the
    # simulated responses
    irf = macro_res.irf(PERIODS)
    repl, signif, seed = 40, 0.1, 1234
    if cum:
        band = irf.cum_errband_mc(
            orth=orth, repl=repl, signif=signif, rng=np.random.default_rng(seed)
        )
    else:
        band = irf.errband_mc(
            orth=orth, repl=repl, signif=signif, rng=np.random.default_rng(seed)
        )
    sims = macro_res.irf_resim(
        orth=orth, repl=repl, steps=PERIODS, rng=np.random.default_rng(seed), cum=cum
    )
    lower = np.quantile(sims, signif / 2, axis=0, method="inverted_cdf")
    upper = np.quantile(sims, 1 - signif / 2, axis=0, method="inverted_cdf")
    assert_allclose(band.lower, lower, rtol=1e-12)
    assert_allclose(band.upper, upper, rtol=1e-12)
    assert np.all(band.lower <= band.upper)
    if not orth:
        # every simulated response at horizon 0 is the identity
        assert_allclose(band.lower[0], np.eye(3), rtol=1e-12)
        assert_allclose(band.upper[0], np.eye(3), rtol=1e-12)


@pytest.mark.parametrize("component", [None, 0, 1])
@pytest.mark.parametrize("orth", [False, True])
def test_err_band_sz1_principal_component(macro_res, orth, component):
    # Sims-Zha method 1: the band is the response plus and minus the normal
    # quantile times sqrt(lambda) w, where (lambda, w) is an eigenpair of
    # the covariance of the simulated responses at horizons 1, ..., periods
    irf = macro_res.irf(PERIODS)
    repl, signif, seed = 60, 0.1, 4321
    comp = None if component is None else np.full((3, 3), component)
    band = irf.err_band_sz1(
        orth=orth,
        repl=repl,
        signif=signif,
        rng=np.random.default_rng(seed),
        component=comp,
    )
    sims = macro_res.irf_resim(
        orth=orth, repl=repl, steps=PERIODS, rng=np.random.default_rng(seed)
    )
    irfs = irf.orth_irfs if orth else irf.irfs
    q = stats.norm.ppf(1 - signif / 2)
    assert_allclose(band.lower[0], irfs[0], rtol=1e-12)
    assert_allclose(band.upper[0], irfs[0], rtol=1e-12)
    assert_allclose(band.lower + band.upper, 2 * irfs, rtol=1e-10)
    for i in range(3):
        for j in range(3):
            cov = np.cov(sims[:, 1:, i, j], rowvar=False)
            eigvals = np.linalg.eigvalsh(cov)
            d = (band.lower[1:, i, j] - irfs[1:, i, j]) / q
            lam = d @ d
            # atol: eigenvector entries can be close to zero
            atol = 1e-8 * lam * np.abs(d).max()
            assert_allclose(cov @ d, lam * d, rtol=1e-6, atol=atol)
            if component is None:
                assert_allclose(lam, eigvals.max(), rtol=1e-8)
            else:
                # documented order: that of scipy.linalg.eig, not sorted
                unsorted = np.real(linalg.eig(cov, left=True, right=False)[0])
                assert_allclose(lam, unsorted[component], rtol=1e-8)


@pytest.mark.parametrize("method", ["err_band_sz2", "err_band_sz3"])
@pytest.mark.parametrize("orth", [False, True])
def test_err_band_sz2_sz3_component(macro_res, method, orth):
    # No independent reference exists for these bands. Check that a valid
    # component is accepted and that the impact period is not perturbed.
    irf = macro_res.irf(PERIODS)
    comp = np.ones((3, 3), dtype=int) if method == "err_band_sz2" else np.ones(3, int)
    band = getattr(irf, method)(
        orth=orth, repl=40, rng=np.random.default_rng(99), component=comp
    )
    irfs = irf.orth_irfs if orth else irf.irfs
    assert band.lower.shape == band.upper.shape == irfs.shape
    assert_allclose(band.lower[0], irfs[0], rtol=1e-12)
    assert_allclose(band.upper[0], irfs[0], rtol=1e-12)
    assert np.all(band.lower <= band.upper)


@pytest.mark.parametrize(
    "method, component, match",
    [
        ("err_band_sz1", np.zeros((3, 2), dtype=int), "Component array must be 3 x 3"),
        ("err_band_sz2", np.zeros((2, 3), dtype=int), "Component array must be 3 x 3"),
        ("err_band_sz3", np.zeros(4, dtype=int), "Component array must be of length"),
    ],
)
def test_err_band_component_wrong_shape(macro_res, method, component, match):
    irf = macro_res.irf(PERIODS)
    with pytest.raises(ValueError, match=match):
        getattr(irf, method)(repl=10, rng=np.random.default_rng(0), component=component)


def _ax_lines(ax):
    return [line.get_ydata() for line in ax.lines]


@pytest.mark.thread_unsafe(reason="uses matplotlib")
@pytest.mark.matplotlib
@pytest.mark.parametrize("orth", [False, True])
def test_plot_asym_bands(macro_res, close_figures, orth):
    irf = macro_res.irf(PERIODS)
    signif = 0.1
    fig = irf.plot(orth=orth, signif=signif)
    irfs = irf.orth_irfs if orth else irf.irfs
    stderr = irf.stderr(orth=orth)
    q = stats.norm.ppf(1 - signif / 2)
    title = "Impulse responses (orthogonalized)" if orth else "Impulse responses"
    assert fig._suptitle.get_text() == title
    assert len(fig.axes) == 9
    for i in range(3):
        for j in range(3):
            ax = fig.axes[3 * i + j]
            assert ax.get_title() == f"{NAMES[j]}$\\rightarrow${NAMES[i]}"
            value, lower, upper, zero = _ax_lines(ax)
            assert_allclose(value, irfs[:, i, j], rtol=1e-12)
            assert_allclose(lower, irfs[:, i, j] - q * stderr[:, i, j], rtol=1e-10)
            assert_allclose(upper, irfs[:, i, j] + q * stderr[:, i, j], rtol=1e-10)
            assert_allclose(zero, [0, 0])


