@pytest.mark.thread_unsafe(reason="uses matplotlib")
@pytest.mark.matplotlib
@pytest.mark.parametrize("stderr_type", ["asym", "mc"])
@pytest.mark.parametrize("orth", [False, True])
def test_plot_cum_effects_bands(macro_res, close_figures, stderr_type, orth):
    irf = macro_res.irf(PERIODS)
    signif = 0.1
    fig = irf.plot_cum_effects(
        orth=orth,
        stderr_type=stderr_type,
        signif=signif,
        repl=30,
        rng=np.random.default_rng(5),
    )
    if orth:
        cum, lr = irf.orth_cum_effects, irf.orth_lr_effects
        title = "Cumulative responses (orthogonalized)"
    else:
        cum, lr = irf.cum_effects, irf.lr_effects
        title = "Cumulative responses"
    if stderr_type == "asym":
        q = stats.norm.ppf(1 - signif / 2)
        se = irf.cum_effect_stderr(orth=orth)
        lower, upper = cum - q * se, cum + q * se
    else:
        band = irf.cum_errband_mc(
            orth=orth, repl=30, signif=signif, rng=np.random.default_rng(5)
        )
        lower, upper = band.lower, band.upper
    assert fig._suptitle.get_text() == title
    for i in range(3):
        for j in range(3):
            lines = _ax_lines(fig.axes[3 * i + j])
            assert len(lines) == 5
            assert_allclose(lines[0], cum[:, i, j], rtol=1e-12)
            assert_allclose(lines[1], lower[:, i, j], rtol=1e-10)
            assert_allclose(lines[2], upper[:, i, j], rtol=1e-10)
            assert_allclose(lines[3], [0, 0])
            assert_allclose(lines[4], [lr[i, j]] * 2, rtol=1e-12)


