    rng = np.random.default_rng(0)
    lower = rng.standard_normal((PERIODS + 1, 3, 3))
    upper = lower + 1
    bands = {
        "errorband": ErrorBand(lower, upper),
        "tuple": (lower, upper),
        "array": np.stack([lower, upper]),
    }[form]
    fig = getattr(irf, method)(err_bands=bands, stderr_type="mc")
    for i in range(3):
        for j in range(3):
            lines = _ax_lines(fig.axes[3 * i + j])
            assert_allclose(lines[1], lower[:, i, j], rtol=1e-12)
            assert_allclose(lines[2], upper[:, i, j], rtol=1e-12)


