@pytest.mark.thread_unsafe(reason="uses matplotlib")
@pytest.mark.matplotlib
def test_plot_svar(macro_svar_res, close_figures):
    irf = macro_svar_res.irf(PERIODS)
    fig = irf.plot(plot_stderr=False)
    assert fig._suptitle.get_text() == "Impulse responses (structural)"
    for i in range(3):
        for j in range(3):
            value, _ = _ax_lines(fig.axes[3 * i + j])
            assert_allclose(value, irf.svar_irfs[:, i, j], rtol=1e-12)
    with pytest.raises(ValueError, match="For SVAR system, set orth=False"):
        irf.plot(orth=True)


def test_irf_pandas_and_ndarray_agree(macro_data, macro_res):
    res = VAR(macro_data.values).fit(maxlags=2)
    irf = res.irf(PERIODS)
    irf_pd = macro_res.irf(PERIODS)
    assert irf_pd.model.names == NAMES
    assert irf.model.names == ["y1", "y2", "y3"]
    for attr in ("irfs", "orth_irfs", "cum_effects", "lr_effects", "P"):
        assert isinstance(getattr(irf_pd, attr), np.ndarray)
        assert_allclose(getattr(irf_pd, attr), getattr(irf, attr), rtol=1e-12)
    assert_allclose(irf_pd.cov(orth=True), irf.cov(orth=True), rtol=1e-12)
